import hmac

USERS = {
    "alice": "secret123",
    "bob": "password456",
}


def verify_password(username, password):
    """校验用户密码是否正确。"""
    stored = USERS.get(username)
    if stored is None:
        return False
    return hmac.compare_digest(password, stored)

